using Oregon.Contracts.Model;

namespace Oregon.Worker.Activities.Models;

/// <summary>A node generated by the deterministic map generator, before the LLM names it.</summary>
/// <param name="Id">Node ID.</param>
/// <param name="Kind">Node kind.</param>
/// <param name="Column">Column index.</param>
/// <param name="PlaceholderName">Fallback name used if the LLM is unavailable.</param>
public sealed record WorldNodeSketch(string Id, NodeKind Kind, int Column, string PlaceholderName);
